export type Skill = "meaning" | "listening" | "writing";
export type Mode = "watch" | "trace" | "copy" | "recall";
export const skillNames = {
  meaning: "Recognition",
  listening: "Listening",
  writing: "Writing",
};
function searchKey(value: string) {
  return value
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[\s'’]/g, "");
}
export type StudyLevel = "hsk1" | "hsk2" | "bonus";
export const levelNames = {
  hsk1: "HSK1",
  hsk2: "HSK2",
  bonus: "Everyday extras",
};
export function isInLevel(item: Item, level: StudyLevel) {
  return level === "bonus"
    ? item.hskLevel === undefined
    : item.hskLevel === (level === "hsk1" ? 1 : 2);
}
export function matchesItem(item: Item, query: string, lesson: string) {
  const group =
    lesson === "all" ||
    (lesson === "hsk1" || lesson === "hsk2" || lesson === "bonus"
      ? isInLevel(item, lesson)
      : item.lesson === lesson);
  const needle = searchKey(query);
  return (
    group &&
    [item.hanzi, item.pinyin, item.english].some((value) =>
      searchKey(value).includes(needle),
    )
  );
}
